    if (screen === SCREEN_PAUSED) drawPaused();
    if (screen === SCREEN_LEG) drawLegComplete(flight, extra?.bonus ?? 0);
    if (screen === SCREEN_OVER) drawOver(flight, best);
    if (extra?.routeOverlay && screen === SCREEN_PLAY) drawRouteOverlay(flight);
  }

  return { draw };
}
